                return json.loads(line)
for n in [31100,31110,31120,31130,31140,31150,31156,31160,31170,31180,31190,31200,31210,31220,31230,31240,31250,31260,31270,31280,31290,31300,31310,31320,31330,31340,31350,31360,31370,31380,31390,31400,31410,31420,31430,31436,31440,31450]:
    obj = load(n)
    if obj is None: continue
    t = obj.get('type')
    ts = obj.get('timestamp')
    msg = obj.get('message', {})
    role = msg.get('role') if isinstance(msg, dict) else None
    content = msg.get('content') if isinstance(msg, dict) else None
    summary=''
    if isinstance(content,str):
        summary = content[:150]
    elif isinstance(content, list):
        parts=[]
        for c in content:
            if isinstance(c, dict):
                if c.get('type')=='text':
                    parts.append('TEXT:'+c.get('text','')[:150])
                elif c.get('type')=='tool_use':
                    parts.append('TOOLUSE:'+c.get('name','')+' '+json.dumps(c.get('input',{}))[:150])
                elif c.get('type')=='tool_result':
                    cc = c.get('content')
                    if isinstance(cc, list):
                        cc = ' '.join(x.get('text','') for x in cc if isinstance(x,dict))
                    parts.append('TOOLRESULT:'+str(cc)[:150])
                elif c.get('type')=='thinking':
                    parts.append('THINK:'+c.get('thinking','')[:150])
        summary = ' | '.join(parts)
    print(n, t, role, ts, summary[:300])
